FUNCTION_BLOCK FB_ValueTracker
    VAR_INPUT
        aaa : DINT := 1;
        bbb : DINT := 0;
    END_VAR
    VAR_OUTPUT
        OUT : DINT;
        UPDATED_CYCLE : DINT;
    END_VAR
    VAR
        CYCLE : DINT := 0;
    END_VAR

    // Increment cycle counter
    CYCLE := CYCLE + 1;

    // Compare aaa and bbb and increment accordingly
    IF aaa = bbb THEN
        aaa := aaa + 1;
    ELSIF aaa > bbb THEN
        bbb := bbb + 1;
    ELSE
        aaa := aaa + 1;
    END_IF

    // Calculate the output difference
    OUT := aaa - bbb;

    // Update the cycle output
    UPDATED_CYCLE := CYCLE;

END_FUNCTION_BLOCK
